SELECT r.*, h.hospital_name, v.plate_number,
(SELECT GROUP_CONCAT(s2.staff_name SEPARATOR ',') FROM waste_staff s2
 WHERE FIND_IN_SET(s2.staff_no, r.staff_nos)) AS staff_names
FROM waste_record r
LEFT JOIN waste_hospital h ON r.hospital_no = h.hospital_no
LEFT JOIN waste_vehicle v ON r.vehicle_no = v.vehicle_no


        AND r.record_date >= #{startDate}


        AND r.record_date <= #{endDate}


        AND r.region = #{region}


        AND h.hospital_name LIKE CONCAT('%', #{hospitalName}, '%')


        AND r.batch_no LIKE CONCAT('%', #{batchNo}, '%')


ORDER BY r.record_date DESC, r.create_time DESC
LIMIT #{offset}, #{size}

SELECT COUNT(*) FROM waste_record r
LEFT JOIN waste_hospital h ON r.hospital_no = h.hospital_no


        AND r.record_date >= #{startDate}


        AND r.record_date <= #{endDate}


        AND r.region = #{region}


        AND h.hospital_name LIKE CONCAT('%', #{hospitalName}, '%')


        AND r.batch_no LIKE CONCAT('%', #{batchNo}, '%')

